import {image,imageStack,caption,icon} from './shared.js';
export function renderScreen(m,header=''){if(m.layout==='split')return m.panels.map(p=>`<div class="panel">${imageStack(p,p.title,true)}${caption(p)}</div>`).join('');return imageStack(m,m.title,m.layout==='hero')+header+caption(m)}
export function renderVideo(m){return `<video class="screen-video" autoplay muted loop playsinline preload="metadata" poster="${m.poster}" aria-label="${m.title}"><source src="${m.video}" type="video/mp4"></video>${caption(m)}`}
export function renderGrid(m){return `<div class="grid">${m.items.map(p=>`<a class="card" href="#${m.layout==='categories'?'edit':'classic'}"><div class="card-image">${imageStack(p,p.title)}</div><div class="card-label"><h2>${p.title}</h2>${m.layout==='stories'?'<span class="text-link">DISCOVER</span>':''}</div></a>`).join('')}</div>${m.layout==='products'?'<a class="view-more text-link" href="#classic">VIEW ALL</a>':''}`}
export function renderServices(){return Array.from({length:3},()=>`<div class="service"><span class="service-icon">${icon('box-new','')}</span><div class="service-copy"><h3>Free Returns</h3><p>All full-priced orders can be returned or exchanged within 14 days</p></div><span class="service-chevron">${icon('chevron-new','')}</span></div>`).join('')}
